-- Fictional players, clubs, sessions and match facts for the public player page characterization
-- (P-PUBLIC-PROFILE, P-RANK-DETAIL, P-MATCH-HISTORY, find by RTR ID). Applied on top of the Prisma migrations,
-- which already seed skill_levels and the six profile banners (court is the default).
-- GENERATED once from the capture session's data description; edit by hand from here on, and rerun
-- apps/api/testdata/tools/capture-playerpages.test.mjs after any change.
-- Rows that only exist to satisfy foreign keys of tables the routes never read (session finalizations,
-- match decisions, assessments, result snapshots) are left out: foreign key checks are off for this load.
BEGIN;
SET LOCAL session_replication_role = replica;

VALUES ('b0000000-0000-4000-8000-000000000001', 'https://example.test/banner-one.png', false,
        TIMESTAMPTZ '2026-11-12 00:00:00+00', 7, TIMESTAMPTZ '2026-11-13 00:00:00+00');

-- The migrations seed the PH / CEB location code.







-- Friday Night is published; Saturday Morning has a publication that is not published yet.



-- Bob has confirmed Gail Guest and his own club record; Dan's confirmation of Gus Guest was revoked.

-- Stored rank rows. No rank formula is approved (#247), so these are plain stored data.
SELECT v.player_id::uuid, v.skill_level_id, v.numeric_rank, v.state::rank_state, '{}'::jsonb,
       (SELECT id FROM ranking_policy_versions ORDER BY version LIMIT 1), 'rank-test-v1',
       TIMESTAMPTZ '2026-01-01 00:00:00+00', TIMESTAMPTZ '2026-11-01 00:00:00+00', TIMESTAMPTZ '2026-11-01 00:00:00+00',
       1, TIMESTAMPTZ '2026-12-01 00:00:00+00', v.recent, v.numeric_rank IS NOT NULL, now()
FROM (VALUES
  ('d1000000-0000-4000-8000-000000000001', 8::smallint, 90.5::numeric, 'established', 5),
  ('d1000000-0000-4000-8000-000000000002', NULL::smallint, NULL::numeric, 'provisional', 0),
  ('d1000000-0000-4000-8000-000000000003', 5::smallint, 70::numeric, 'needs_reassessment', 2),
  ('d1000000-0000-4000-8000-000000000005', 3::smallint, 50::numeric, 'established', 4),
  ('d1000000-0000-4000-8000-000000000006', 0::smallint, 10::numeric, 'established', 0)
) AS v(player_id, skill_level_id, numeric_rank, state, recent);

COMMIT;
